const claimed = new Set<string>();
localBindingNames.forEach(name => {
  let newName = name;
  if (!fileBindings.has(name) && !claimed.has(name)) {
    // This name is only occupied by the helper-local binding itself,
    // which is being renamed or kept, so it is not a collision here.
    this._collisionNames.delete(name);
  }
  while (this._collisionNames.has(newName)) newName = "_" + newName;

  if (newName !== name) {
    this._renames[name] = newName;
    claimed.add(newName);
    this._collisionNames.add(newName);
  }
});

